<template>
  <div class="video-world page-shell">
    <div class="page-header">
      <div>
        <div class="page-kicker">Video Studio</div>
        <h2 class="page-title">影视界</h2>
      </div>
      <div class="header-actions">
        <el-button @click="agentVisible = true">Agent</el-button>
        <el-button @click="assetVisible = true">素材库</el-button>
        <el-button @click="canvasVisible = true">画布</el-button>
        <el-button @click="configVisible = true">模型配置</el-button>
        <el-tooltip content="刷新" placement="bottom"><el-button class="refresh-button" :loading="loading" circle aria-label="刷新" @click="loadAll"><el-icon><Refresh /></el-icon></el-button></el-tooltip>
      </div>
    </div>

    <div class="workspace-grid">
      <el-card shadow="never" class="create-card">
        <template #header><div class="panel-title">视频创作</div></template>
        <el-form label-position="top">
          <el-alert v-if="form.project_id" class="project-role-banner" type="success" :closable="false"><template #title>当前分镜使用项目视频职责配置</template><span>模型、Provider / Key 和端点模板以项目“生产职责”设置为准。</span><el-button text type="primary" @click="form.project_id = undefined">退出项目职责</el-button></el-alert>
          <el-form-item label="模型">
            <el-select v-model="form.model" placeholder="选择视频模型" @change="applyModelDefaults">
              <el-option v-for="item in models.filter((model) => model.enabled)" :key="item.id" :value="item.model" :label="`${item.display_name}（可用 Key：${item.available_key_count}）`" />
            </el-select>
          </el-form-item>
          <el-collapse>
            <el-collapse-item title="高级：锁定调用来源（可选）" name="source-lock">
              <el-form-item label="Provider / Key">
                <el-select v-model="form.source" clearable placeholder="默认：所有支持该模型的可用 Key 自动轮询">
                  <el-option v-for="item in sources" :key="item.value" :label="item.label" :value="item.value" />
                </el-select>
              </el-form-item>
            </el-collapse-item>
          </el-collapse>
          <el-form-item label="视觉风格">
            <div class="style-collapse-head"><span>{{ selectedStyle ? `当前：${selectedStyle.name}` : '未选择，使用模型默认风格' }}</span><el-button size="small" text type="primary" @click="stylePickerExpanded = !stylePickerExpanded">{{ stylePickerExpanded ? '收起风格' : '选择视觉风格' }}</el-button></div>
            <template v-if="stylePickerExpanded"><div class="style-preset-tabs"><el-button size="small" :type="styleCategory === 'live' ? 'primary' : 'default'" @click="styleCategory = 'live'">AI 真人剧</el-button><el-button size="small" :type="styleCategory === 'anim' ? 'primary' : 'default'" @click="styleCategory = 'anim'">AI 漫剧</el-button><el-button v-if="selectedStyleId" size="small" text @click="clearStylePreset">清除风格</el-button></div><div class="style-preset-strip"><button v-for="preset in visibleStylePresets" :key="preset.id" type="button" class="style-preset" :class="{ 'is-selected': selectedStyleId === preset.id }" @click="selectStylePreset(preset)"><el-image class="style-preset__image" :src="preset.thumbnail" fit="cover" /><strong>{{ preset.name }}</strong><span>{{ preset.tagline }}</span></button></div><small class="style-license">风格缩略图与模板来自 ArcReel，按 AGPL-3.0 复用。</small></template>
          </el-form-item>
          <div class="form-row">
            <el-form-item label="生成模式"><el-select v-model="form.mode"><el-option label="文生视频" value="text" /><el-option label="首尾帧" value="keyframe" /><el-option label="图片 / 音频参考" value="reference" /></el-select></el-form-item>
            <el-form-item label="视频时长"><el-select v-model="form.seconds"><el-option v-for="seconds in secondsOptions" :key="seconds" :label="`${seconds} 秒`" :value="seconds" /></el-select></el-form-item>
          </div>
          <div class="form-row">
            <el-form-item label="画幅"><el-select v-model="form.aspect_ratio"><el-option v-for="ratio in ratioOptions" :key="ratio" :label="ratio" :value="ratio" /></el-select></el-form-item>
            <el-form-item label="随机种子（可选）"><el-input-number v-model="form.seed" :min="0" :controls="false" placeholder="固定结果倾向" /></el-form-item>
          </div>
          <el-form-item label="提示词"><el-input v-model="form.prompt" type="textarea" :rows="5" placeholder="描述主体、动作、场景、镜头和光线。" /></el-form-item>
          <template v-if="form.mode === 'keyframe'">
            <el-form-item label="首帧图片 URL"><el-input v-model="form.first_frame" placeholder="https://..." /></el-form-item>
            <el-form-item label="尾帧图片 URL"><el-input v-model="form.last_frame" placeholder="https://..." /></el-form-item>
          </template>
          <template v-if="form.mode === 'reference'">
            <el-form-item label="参考图片 URL（每行一个，最多 5 张）"><el-input v-model="referenceImages" type="textarea" :rows="3" /></el-form-item>
            <el-form-item label="参考音频 URL（每行一个，最多 3 段）"><el-input v-model="referenceAudios" type="textarea" :rows="2" /></el-form-item>
          </template>
          <el-button type="primary" class="generate-button" :loading="generating" @click="generate">开始生成</el-button>
        </el-form>
      </el-card>

      <el-card shadow="never" class="task-card">
        <template #header><div class="panel-title"><span>视频任务</span><el-button size="small" text type="primary" @click="videoHistoryExpanded = !videoHistoryExpanded">{{ videoHistoryExpanded ? '收起历史' : `生产历史（${Math.max(tasks.length - 1, 0)}）` }}</el-button></div></template>
        <el-empty v-if="!tasks.length" description="暂无视频任务" />
        <div v-else class="task-list">
          <article v-for="task in displayedTasks" :key="task.id" class="task-item">
            <div class="task-header"><div class="task-title">{{ task.model }} · {{ modeLabel(task.mode) }} · {{ task.seconds }} 秒 <el-tag v-if="task.style_preset_name" size="small" effect="plain">{{ task.style_preset_name }}</el-tag></div><div class="task-actions"><el-tag :type="statusType(task.status)">{{ statusLabel(task.status) }}</el-tag><el-button size="small" @click="openVideoTaskDetail(task)">详情</el-button><el-button size="small" :loading="refreshingId === task.id" @click="refresh(task)">查询</el-button><el-button size="small" text type="danger" @click="removeTask(task)">删除</el-button></div></div>
            <button type="button" class="task-prompt" @click="openVideoTaskDetail(task)">{{ task.prompt }}</button>
            <div class="task-config-strip"><el-tag v-if="task.request_params?.aspect_ratio" size="small" effect="plain">{{ task.request_params.aspect_ratio }}</el-tag><el-tag v-if="task.request_params?.size" size="small" effect="plain">{{ task.request_params.size }}</el-tag><el-tag v-if="task.provider" size="small" effect="plain">{{ task.provider }}</el-tag><el-tag v-if="task.style_preset_name" size="small" type="success" effect="plain">风格：{{ task.style_preset_name }}</el-tag></div>
            <div class="task-meta">任务 #{{ task.id }} · Key #{{ task.api_key_id || '-' }} · {{ formatTime(task.created_at) }}</div>
            <div v-if="pollingWaitSeconds(task.id)" class="task-polling-hint">{{ pollingState(task.id).limited ? '上游限流' : '自动查询间隔' }} · {{ pollingWaitSeconds(task.id) }} 秒后可查询</div>
            <video v-if="task.video_url" class="video-preview" :src="task.video_url" controls preload="metadata" />
            <a v-if="task.video_url" :href="task.video_url" target="_blank" rel="noopener" class="video-link">打开 / 下载视频</a>
            <p v-if="task.error_detail" class="error-message">{{ task.error_detail }}</p>
          </article>
        </div>
      </el-card>
    </div>

    <el-dialog v-model="agentVisible" title="Agent" width="900px" class="agent-dialog">
      <div class="agent-layout">
        <aside class="agent-projects"><div class="agent-projects__head"><strong>创作项目</strong><el-button size="small" @click="resetCreativeDraft">新建</el-button></div><el-scrollbar><button v-for="project in creativeProjects" :key="project.id" class="agent-project-item" :class="{ 'is-active': creativeProject?.id === project.id }" @click="selectCreativeProject(project)"><strong>{{ project.title }}</strong><span>{{ formatTime(project.updated_at) }}</span></button></el-scrollbar></aside>
        <section class="agent-workspace">
          <template v-if="!creativeProject">
            <el-form label-position="top"><el-form-item label="项目名称"><el-input v-model="creativeDraft.title" placeholder="例如：雨夜失踪案" /></el-form-item><el-form-item label="默认画幅"><el-select v-model="creativeDraft.default_aspect_ratio"><el-option label="竖屏 9:16（移动端）" value="9:16" /><el-option label="横屏 16:9" value="16:9" /><el-option label="方形 1:1" value="1:1" /></el-select></el-form-item><el-form-item label="小说 / 故事 / 创作构想（可选）"><el-input v-model="creativeDraft.source_text" type="textarea" :rows="10" placeholder="可粘贴创作构想，或直接上传小说、剧本附件。" /></el-form-item><el-form-item label="项目资料附件"><el-upload v-model:file-list="creativeDraftFiles" :auto-upload="false" multiple accept=".txt,.md,.docx,.pdf"><el-button>选择 TXT、MD、DOCX、PDF</el-button><template #tip><div class="el-upload__tip">可直接用附件创建项目，单文件最大 20MB。</div></template></el-upload></el-form-item><el-button type="primary" :loading="creatingCreativeProject" @click="createCreativeProject">创建项目</el-button></el-form>
          </template>
          <template v-else>
            <div class="agent-project-title"><div><div class="page-kicker">Creative Project</div><h3>{{ creativeProject.title }}</h3></div><div><el-button @click="openProjectRoles">生产职责</el-button><el-button text type="danger" @click="removeCreativeProject">删除项目</el-button></div></div>
            <div class="project-aspect-control"><span>项目默认画幅</span><el-select v-model="creativeProject.default_aspect_ratio" size="small" @change="saveProjectAspectRatio"><el-option label="竖屏 9:16（移动端）" value="9:16" /><el-option label="横屏 16:9" value="16:9" /><el-option label="方形 1:1" value="1:1" /></el-select><small>分镜可单独覆盖；移动端视频建议使用 9:16。</small></div>
            <el-alert class="agent-source-guide" type="info" :closable="false"><template #title><strong>模型与来源说明</strong></template><div>先输入 Key 管理中已配置的文本模型。<b>自动</b>会在所有提供商的可用 Key 间轮询；选择<b>提供商</b>会在该提供商的同模型 Key 间轮询；选择<b>指定 Key</b>只调用该条 Key。</div></el-alert>
            <div class="agent-controls"><el-input v-model="creativeAgent.model" placeholder="输入文本模型后按回车加载来源" @keyup.enter="loadCreativeAgentSources" @blur="loadCreativeAgentSources" /><el-select v-model="creativeAgent.source" :loading="loadingCreativeSources" clearable placeholder="自动：所有提供商 / Key 轮询"><el-option label="自动：所有提供商 / Key 轮询" value="" /><el-option-group v-if="creativeAgentSources.providers.length" label="按提供商轮询"><el-option v-for="provider in creativeAgentSources.providers" :key="`provider:${provider}`" :label="`${provider}：同模型 Key 自动轮询`" :value="`provider:${provider}`" /></el-option-group><el-option-group v-if="creativeAgentSources.keys.length" label="锁定单个 Key"><el-option v-for="key in creativeAgentSources.keys" :key="`key:${key.id}`" :label="`${key.provider} | #${key.id} ${key.name}`" :value="`key:${key.id}`" /></el-option-group></el-select></div>
            <el-steps :active="creativeStageIndex" finish-status="success" simple><el-step title="内容分析" /><el-step title="剧本" /><el-step title="分镜" /></el-steps>
            <div class="agent-actions"><el-button :loading="creativeRunning === 'analysis'" @click="runAgent('analysis')">生成分析</el-button><el-button :disabled="!creativeProject.analysis?.summary" :loading="creativeRunning === 'script'" @click="runAgent('script')">生成剧本</el-button><el-button type="primary" :disabled="!creativeProject.script?.episodes?.length" :loading="creativeRunning === 'storyboard'" @click="runAgent('storyboard')">生成分镜</el-button></div><section class="director-actions"><div class="director-actions__head"><div><strong>导演 Agent</strong><span v-if="directorStatus">{{ directorStatus.shots?.length || 0 }} 个镜头 · {{ directorStatus.plan_version || '未版本化' }}</span></div><el-tag v-if="directorStatus" size="small" :type="directorStatus.review_status?.includes('review') ? 'warning' : 'info'">{{ directorReviewLabel }}</el-tag></div><div class="director-actions__buttons"><el-button type="primary" :loading="directorRunning === 'storyboard'" @click="runDirectorStoryboard">一键分镜</el-button><el-button :disabled="!directorStatus?.shots?.length" :loading="directorRunning === 'produce'" @click="produceDirectorShots">一键批量生产</el-button><el-button :disabled="!directorStatus?.shots?.length" :loading="directorRunning === 'schedule'" @click="autoScheduleDirector">一键自动排片</el-button></div><p v-if="directorStatus" class="director-actions__meta">视频 {{ directorStatus.video_count }} · 音频 {{ directorStatus.audio_count }} · 时间线 {{ directorStatus.timeline_count }} · 已完成镜头 {{ directorCompletedShotCount }}/{{ directorStatus.shots.length }}</p><p v-if="directorBlockers.length" class="director-actions__blockers">阻塞：{{ directorBlockers.map((item) => `镜 ${Number(item.shot_index) + 1} ${item.reason || item.error_detail || ''}`).join('；') }}</p><p v-if="directorStatus?.shot_statuses?.some((item) => item.tasks?.video?.error_detail || item.tasks?.audio?.error_detail || item.tasks?.subtitle?.error_detail)" class="director-actions__blockers">任务错误：{{ directorStatus.shot_statuses.filter((item) => item.tasks?.video?.error_detail || item.tasks?.audio?.error_detail || item.tasks?.subtitle?.error_detail).map((item) => `镜 ${Number(item.shot_index) + 1}`).join('、') }}</p></section><section class="workflow-panel"><div class="workflow-panel__head"><div><strong>制作工作流</strong><span>{{ workflowStatusLabel }}</span></div><div class="asset-task-actions"><el-button size="small" :loading="creatingWorkflowPlan" @click="createWorkflowPlan">生成制作计划</el-button><el-button v-if="projectWorkflow?.status?.startsWith('awaiting_')" size="small" type="primary" :loading="reviewingWorkflow" @click="reviewWorkflow('approve')">批准继续</el-button><el-button v-if="projectWorkflow?.status === 'running'" size="small" @click="reviewWorkflow('pause')">暂停</el-button><el-button v-if="projectWorkflow?.status === 'paused'" size="small" type="primary" @click="reviewWorkflow('resume')">恢复</el-button></div></div><el-alert v-if="projectWorkflow?.plan" type="info" :closable="false"><template #title>制作计划</template><span>预计 {{ projectWorkflow.plan.total_duration_seconds || '-' }} 秒 · {{ projectWorkflow.plan.shot_count || '-' }} 个镜头 · {{ projectWorkflow.plan.aspect_ratio || '默认画幅' }} · 原生音频默认保留并识别字幕</span><div v-if="projectVisualStyle" class="workflow-style"><span>项目视觉风格：{{ projectVisualStyle }}</span><el-button size="small" type="primary" plain @click="applyProjectStyle">应用到视频生成</el-button></div></el-alert><div v-if="projectWorkflow?.tasks?.length" class="workflow-task-list"><el-tag v-for="task in projectWorkflow.tasks" :key="task.id" :type="workflowTaskType(task.status)">{{ task.stage }} · {{ workflowTaskLabel(task.status) }}</el-tag></div><p v-if="projectWorkflow?.error_detail" class="error-message">{{ projectWorkflow.error_detail }}</p></section>
            <div v-if="creativeProject.storyboard?.length" class="storyboard-batch-actions"><span>已选 {{ selectedStoryboardIndexes.length }} 个分镜</span><el-button size="small" @click="toggleAllStoryboardShots">{{ selectedStoryboardIndexes.length === creativeProject.storyboard.length ? '取消全选' : '全选分镜' }}</el-button><el-select v-model="storyboardConcurrency" size="small" class="storyboard-concurrency" aria-label="批量生成并发数"><el-option v-for="value in [1, 2, 3, 5]" :key="value" :label="`并发 ${value}`" :value="value" /></el-select><el-button size="small" type="primary" :disabled="!selectedStoryboardIndexes.length" :loading="generatingStoryboard" @click="generateSelectedStoryboardVideos">批量生成视频</el-button></div>
            <el-collapse v-model="agentPanels"><el-collapse-item title="项目资料与附件" name="source"><p class="agent-source">{{ creativeProject.source_text }}</p><div class="project-attachment-actions"><el-upload :show-file-list="false" multiple accept=".txt,.md,.docx,.pdf" :before-upload="uploadProjectAttachment"><el-button size="small" :loading="uploadingProjectAttachment">上传小说 / 剧本附件</el-button></el-upload><span>支持 TXT、Markdown、DOCX、PDF，单文件最大 20MB。</span></div><div v-if="projectAttachments.length" class="project-attachment-list"><el-tag v-for="item in projectAttachments" :key="item.id" closable @close="removeProjectAttachment(item)">{{ item.original_name }} · {{ item.text_length }} 字</el-tag></div></el-collapse-item><el-collapse-item title="内容分析" name="analysis"><pre v-if="creativeProject.analysis?.summary" class="agent-json">{{ JSON.stringify(creativeProject.analysis, null, 2) }}</pre><el-empty v-else description="等待 Agent 分析" /></el-collapse-item><el-collapse-item title="剧本" name="script"><pre v-if="creativeProject.script?.episodes?.length" class="agent-json">{{ JSON.stringify(creativeProject.script, null, 2) }}</pre><el-empty v-else description="完成内容分析后生成剧本" /></el-collapse-item><el-collapse-item title="分镜" name="storyboard"><div v-if="creativeProject.storyboard?.length" class="storyboard-list"><article v-for="(shot, index) in creativeProject.storyboard" :key="`${shot.scene_no}-${shot.shot_no}-${index}`" class="storyboard-item" :class="{ 'is-selected': selectedStoryboardIndex === index }" @click="selectStoryboardShot(shot, index)"><div class="storyboard-item__head"><el-checkbox :model-value="selectedStoryboardIndexes.includes(index)" @click.stop @change="toggleStoryboardShot(index)" /><strong>场 {{ shot.scene_no }} · 镜 {{ shot.shot_no }} · {{ shot.duration_seconds }} 秒</strong><el-tag v-if="storyboardTaskByIndex[index]" size="small" :type="statusType(storyboardTaskByIndex[index].status)">{{ statusLabel(storyboardTaskByIndex[index].status) }}</el-tag><template v-if="directorStatus?.shot_statuses?.find((item) => item.shot_index === index)?.tasks"><el-tag v-for="stage in ['video', 'audio', 'subtitle']" :key="stage" size="small" effect="plain" :type="workflowTaskType(directorStatus.shot_statuses.find((item) => item.shot_index === index).tasks[stage]?.status)">{{ { video: '视频', audio: '配音', subtitle: '字幕' }[stage] }} {{ workflowTaskLabel(directorStatus.shot_statuses.find((item) => item.shot_index === index).tasks[stage]?.status || 'not_created') }}<template v-if="directorStatus.shot_statuses.find((item) => item.shot_index === index).tasks[stage]?.retry_count"> · {{ directorStatus.shot_statuses.find((item) => item.shot_index === index).tasks[stage].retry_count }}次重试</template></el-tag></template></div><p>{{ shot.visual_prompt }}</p><small>{{ shot.camera }} · {{ shot.motion }}</small><el-tag v-if="directorStatus?.shot_statuses?.find((item) => item.shot_index === index)?.status === 'planned' && directorStatus?.shot_statuses?.find((item) => item.shot_index === index)?.has_historical_artifacts" size="small" type="warning">需重新生产</el-tag><div class="storyboard-actions"><el-button size="small" @click.stop="openStoryboardEditor(shot, index)">编辑分镜</el-button><el-button size="small" type="warning" :loading="directorRunning === `produce-${index}`" @click.stop="produceDirectorShot(index)">重新生产此镜头</el-button><el-button size="small" type="primary" @click.stop="useStoryboardShot(shot)">用于视频生成</el-button></div></article></div><el-empty v-else description="完成剧本后生成分镜" /></el-collapse-item><el-collapse-item title="项目美术资产" name="images"><div class="project-image-create"><div class="project-image-create__head"><strong>角色、场景与分镜参考图</strong><span>使用项目“图片生成”职责配置。</span></div><el-input v-model="projectImageDraft.title" placeholder="资产名称，例如：女主角林夏" /><el-select v-model="projectImageDraft.asset_type"><el-option label="角色设定图" value="character" /><el-option label="场景概念图" value="scene" /><el-option label="分镜参考图" value="storyboard_reference" /></el-select><el-select v-if="projectImageDraft.asset_type === 'storyboard_reference'" v-model="projectImageDraft.storyboard_shot_index" placeholder="关联分镜"><el-option v-for="(shot, index) in creativeProject.storyboard || []" :key="index" :label="`场 ${shot.scene_no} · 镜 ${shot.shot_no}`" :value="index" /></el-select><el-input v-model="projectImageDraft.prompt" type="textarea" :rows="3" placeholder="描述角色外观、场景氛围或分镜构图。" /><el-button type="primary" :loading="creatingProjectImage" @click="createProjectImage">生成资产图</el-button></div><div v-if="projectImageAssets.length" class="project-image-asset-list"><article v-for="asset in projectImageAssets" :key="asset.id" class="project-image-asset"><div class="project-image-asset__head"><strong>{{ asset.title }}</strong><el-tag :type="statusType(asset.status)">{{ statusLabel(asset.status) }}</el-tag></div><p>{{ asset.prompt }}</p><el-image v-for="result in asset.results.filter((item) => item.status === 'success')" :key="result.id" :src="result.local_url || result.image_url" fit="cover" :preview-src-list="asset.results.filter((item) => item.status === 'success').map((item) => item.local_url || item.image_url)" preview-teleported /><p v-if="asset.error_detail" class="error-message">{{ asset.error_detail }}</p></article></div><el-empty v-else description="暂无角色、场景或分镜参考图" /></el-collapse-item><el-collapse-item title="视频片段与时间线" name="video-timeline"><div v-if="projectVideoTasks.length" class="project-video-task-list"><article v-for="item in projectVideoTasks" :key="item.id" class="project-video-task-item"><div><strong>镜 {{ (item.storyboard_shot_index ?? 0) + 1 }} · {{ item.model }} · {{ item.seconds }} 秒</strong><p>{{ item.prompt }}</p><el-tag :type="statusType(item.status)">{{ statusLabel(item.status) }}</el-tag></div><video v-if="item.video_url" :src="item.video_url" controls preload="metadata" /><el-tag v-if="item.status === 'completed' && item.has_native_audio !== null" size="small" :type="item.has_native_audio ? 'success' : 'info'">{{ item.has_native_audio ? '已保留原声' : '无原声音轨' }}</el-tag><el-tag v-if="item.request_params?.reference_asset_ids?.length" size="small" type="success">已使用 {{ item.request_params.reference_asset_ids.length }} 个一致性参考图</el-tag><div class="asset-task-actions"><el-button size="small" :loading="refreshingId === item.id" @click="refreshProjectVideoTask(item)">查询状态</el-button><el-button v-if="item.status === 'completed' && item.storyboard_shot_index !== null && item.storyboard_shot_index !== undefined" size="small" :type="selectedStoryboardVideoIds.has(item.id) ? 'success' : 'primary'" @click="selectStoryboardVideoCandidate(item)">{{ selectedStoryboardVideoIds.has(item.id) ? '当前定稿' : '设为定稿' }}</el-button><el-button v-if="item.status === 'failed' && item.storyboard_shot_index !== null && item.storyboard_shot_index !== undefined" size="small" type="warning" :loading="retryingStoryboard === item.storyboard_shot_index" @click="retryStoryboardVideo(item)">重试生成</el-button><el-button v-if="item.status === 'completed' && item.storyboard_shot_index === null && !timelineHasSource('video_task', item.id)" size="small" @click="addTimelineItem('video', 'video_task', item.id)">加入视频轨</el-button><el-tag v-if="item.status === 'completed' && item.storyboard_shot_index === null && timelineHasSource('video_task', item.id)" size="small" type="success">已在视频轨</el-tag></div></article></div><el-empty v-else description="暂无项目视频片段" /></el-collapse-item><el-collapse-item title="配音与字幕" name="audio"><div class="voice-profile-strip"><div class="voice-profile-strip__head"><strong>项目音色设定</strong><span>角色音色会保存角色名称快照，后续修改不影响已生成任务。</span></div><div class="voice-profile-create"><el-select v-model="voiceProfileDraft.profile_type"><el-option label="旁白" value="narrator" /><el-option label="角色" value="character" /></el-select><el-select v-if="voiceProfileDraft.profile_type === 'character'" v-model="voiceProfileDraft.character_asset_id" placeholder="选择角色"><el-option v-for="asset in characterAssets" :key="asset.id" :label="asset.title" :value="asset.id" /></el-select><el-input v-model="voiceProfileDraft.name" placeholder="设定名称" /><el-select v-model="voiceProfileDraft.voice"><el-option label="alloy" value="alloy" /><el-option label="nova" value="nova" /><el-option label="shimmer" value="shimmer" /></el-select><el-button size="small" type="primary" :loading="savingVoiceProfile" @click="saveVoiceProfile">保存</el-button></div><div v-if="projectVoiceProfiles.length" class="voice-profile-list"><el-tag v-for="profile in projectVoiceProfiles" :key="profile.id" closable @close="removeVoiceProfile(profile)">{{ profile.name }} · {{ profile.voice }}</el-tag></div><span v-else class="panel-muted">暂无音色设定，可先使用临时音色加入队列。</span></div><div class="audio-create"><div class="audio-create__selectors"><el-radio-group v-model="audioDraft.speaker_type"><el-radio-button label="narrator">旁白</el-radio-button><el-radio-button label="character">角色台词</el-radio-button></el-radio-group><el-select v-if="audioDraft.speaker_type === 'character'" v-model="audioDraft.character_asset_id" clearable placeholder="选择角色"><el-option v-for="asset in characterAssets" :key="asset.id" :label="asset.title" :value="asset.id" /></el-select><el-select v-model="audioDraft.voice_profile_id" clearable placeholder="音色设定"><el-option v-for="profile in selectedVoiceProfiles" :key="profile.id" :label="`${profile.name} · ${profile.voice}`" :value="profile.id" /></el-select><el-select v-model="audioDraft.voice"><el-option label="alloy" value="alloy" /><el-option label="nova" value="nova" /><el-option label="shimmer" value="shimmer" /></el-select></div><el-input v-model="audioDraft.speaker_name" v-if="audioDraft.speaker_type === 'character' && !audioDraft.character_asset_id" placeholder="临时角色名称（可选音色设定）" /><el-input v-model="audioDraft.text" type="textarea" :rows="3" placeholder="输入旁白或角色台词；提交后进入配音队列。" /><div class="audio-create__actions"><el-button type="primary" :loading="creatingAudio" @click="createAudio">加入配音队列</el-button></div></div><div v-if="projectAudioTasks.length" class="audio-task-list"><article v-for="item in projectAudioTasks" :key="item.id" class="audio-task-item"><div><strong>{{ item.speaker_name_snapshot || (item.speaker_type === 'character' ? '未标注角色' : '旁白') }} · {{ item.voice }}</strong><p>{{ item.input_text }}</p><el-tag :type="statusType(item.status)">{{ statusLabel(item.status) }}</el-tag><small class="audio-task-meta">{{ item.model }} · {{ item.status === 'pending' ? `队列 ${Number(item.queue_position ?? 0) + 1}` : '配音任务' }}</small></div><audio v-if="item.audio_url" :src="item.audio_url" controls /><div class="asset-task-actions"><el-button v-if="item.status === 'pending'" size="small" :disabled="audioQueueBusy === item.id" @click="moveAudioQueueItem(item, -1)">上移</el-button><el-button v-if="item.status === 'pending'" size="small" :disabled="audioQueueBusy === item.id" @click="moveAudioQueueItem(item, 1)">下移</el-button><el-button v-if="item.status === 'pending'" size="small" text type="danger" @click="removeAudio(item)">移除</el-button><el-button v-if="item.status === 'failed'" size="small" type="warning" :loading="audioQueueBusy === item.id" @click="retryAudio(item)">重试</el-button><el-button v-if="item.status === 'completed'" size="small" :loading="creatingSubtitle === item.id" @click="createSubtitle(item)">识别字幕</el-button><el-button v-if="item.status === 'completed' && !timelineHasSource('audio_task', item.id)" size="small" @click="addTimelineItem('audio', 'audio_task', item.id)">加入音轨</el-button><el-tag v-if="item.status === 'completed' && timelineHasSource('audio_task', item.id)" size="small" type="success">已在音轨</el-tag></div></article></div><el-empty v-else description="暂无项目音轨" /><div v-if="projectSubtitleTasks.length" class="subtitle-task-list"><article v-for="item in projectSubtitleTasks" :key="item.id" class="subtitle-task-item"><strong>{{ item.model }} · {{ statusLabel(item.status) }}</strong><p>{{ item.transcript }}</p><el-input v-if="item.srt_content" v-model="item.srt_content" type="textarea" :rows="5" /><div class="asset-task-actions"><el-button v-if="item.status === 'completed'" size="small" :loading="savingSubtitle === item.id" @click="saveProjectSubtitle(item)">保存字幕</el-button><el-button v-if="item.srt_content" size="small" @click="downloadProjectSubtitle(item)">下载 SRT</el-button><el-button v-if="item.status === 'completed' && !timelineHasSource('subtitle_task', item.id)" size="small" @click="addTimelineItem('subtitle', 'subtitle_task', item.id)">加入字幕轨</el-button><el-tag v-if="item.status === 'completed' && timelineHasSource('subtitle_task', item.id)" size="small" type="success">已在字幕轨</el-tag></div></article></div><div class="project-timeline"><div class="project-timeline__head"><strong>项目时间线</strong><span>{{ projectTimeline.length }} 个资产</span></div><section v-if="previewVideoUrl" class="project-preview" :style="{ aspectRatio: previewAspectRatio }"><video :src="previewVideoUrl" controls preload="metadata" /><span>{{ projectExports.some((item) => item.status === 'completed') ? '最终成片预览' : '定稿镜头素材预览' }} · {{ previewAspectRatio }}</span></section><div v-for="track in ['video', 'audio', 'subtitle']" :key="track" class="timeline-track"><strong>{{ { video: '视频轨', audio: '音轨', subtitle: '字幕轨' }[track] }}</strong><div class="timeline-items"><article v-for="(item, index) in projectTimeline.filter((entry) => entry.track === track).sort((a, b) => a.position - b.position)" :key="item.id" class="timeline-item"><strong>{{ track === 'video' && item.storyboard_shot_index !== null && item.storyboard_shot_index !== undefined ? `镜 ${item.storyboard_shot_index + 1} · 定稿` : `${item.source_type} #${item.source_id}` }}</strong><div class="timeline-reorder"><el-button size="small" :disabled="index === 0" @click="moveTimelineItem(item, -1)">上移</el-button><el-button size="small" :disabled="index === projectTimeline.filter((entry) => entry.track === track).length - 1" @click="moveTimelineItem(item, 1)">下移</el-button></div><el-input-number v-model="item.position" :min="0" :controls="false" aria-label="片段顺序" /><el-input-number v-model="item.offset_ms" :min="0" :step="100" :controls="false" aria-label="起始偏移毫秒" /><el-input-number v-model="item.duration_ms" :min="1" :step="1000" :controls="false" placeholder="时长毫秒" aria-label="片段时长毫秒" /><el-button size="small" :loading="savingTimelineItem === item.id" @click="saveTimelineItem(item)">保存</el-button><el-button size="small" text type="danger" @click="removeTimelineItem(item)">移除</el-button></article><span v-if="!projectTimeline.some((entry) => entry.track === track)">暂无资产</span></div></div></div><section class="project-export"><div class="project-export__head"><div><strong>成片导出</strong><span :class="{ 'is-ready': ffmpegPreflight?.available }">{{ ffmpegPreflight?.available ? 'FFmpeg 已就绪' : 'FFmpeg 未就绪' }}</span></div><el-button size="small" type="primary" :disabled="!ffmpegPreflight?.available" :loading="creatingProjectExport" @click="createProjectExport">导出 MP4</el-button></div><el-radio-group v-model="projectExportAudioStrategy" size="small" class="project-export__strategy"><el-radio-button label="preserve">保留视频原声</el-radio-button><el-radio-button label="mute">仅时间线配音</el-radio-button><el-radio-button label="overlay">原声叠加配音</el-radio-button></el-radio-group><p class="project-export__hint">保留原声不混入配音；仅时间线配音会静音视频原声；叠加配音会保留原声并混音。</p><p v-if="!ffmpegPreflight?.available" class="error-message">{{ ffmpegPreflight?.error || '正在检查包内 FFmpeg' }}</p><p v-else class="project-export__version">{{ ffmpegPreflight.version }}</p><div v-if="projectExports.length" class="project-export__tasks"><article v-for="item in projectExports" :key="item.id" class="project-export__task"><div><strong>成片 #{{ item.id }}</strong><el-tag size="small" :type="statusType(item.status)">{{ statusLabel(item.status) }}</el-tag><span class="project-export__meta">{{ { preserve: '保留视频原声', mute: '仅时间线配音', overlay: '原声叠加配音' }[item.audio_strategy] || '保留视频原声' }}<template v-if="item.duration_ms"> · {{ (item.duration_ms / 1000).toFixed(2) }} 秒</template></span></div><p v-if="item.error_detail" class="error-message">{{ item.error_detail }}</p><div v-if="item.status === 'completed'" class="asset-task-actions"><el-button size="small" type="primary" @click="downloadProjectExport(item)">下载 MP4</el-button><el-button v-if="item.subtitle_url" size="small" @click="downloadProjectExport(item, 'srt')">下载 SRT</el-button><el-button v-if="item.manifest_url" size="small" @click="downloadProjectExport(item, 'manifest')">下载清单</el-button></div></article></div></section></el-collapse-item></el-collapse>
          </template>
        </section>
      </div>
    </el-dialog>


    <el-dialog v-model="roleConfigVisible" title="项目生产职责" width="760px" class="role-config-dialog">
      <el-alert type="info" :closable="false" title="每项职责独立选择模型与来源。自动会轮询所有 Provider 的同模型 Key；Provider 会轮询该 Provider 的同模型 Key；指定 Key 会严格锁定单条 Key。" />
      <div class="role-config-list"><article v-for="role in productionRoles" :key="role.id" class="role-config-item"><div class="role-config-item__head"><strong>{{ role.label }}</strong><span>{{ role.description }}</span></div><el-input v-model="role.model" placeholder="模型名称" /><el-select v-model="role.source_mode"><el-option label="自动轮询" value="auto" /><el-option label="指定 Provider" value="provider" /><el-option label="指定 Key" value="key" /></el-select><el-input v-if="role.source_mode === 'provider'" v-model="role.provider" placeholder="Provider 名称" /><el-input-number v-if="role.source_mode === 'key'" v-model="role.api_key_id" :min="1" placeholder="Key ID" /><el-select v-if="role.id === 'video'" v-model="role.endpoint_template_id" clearable placeholder="视频端点模板"><el-option v-for="item in endpointTemplates" :key="item.id" :label="item.name" :value="item.id" /></el-select><el-switch v-model="role.enabled" active-text="启用" inactive-text="停用" /><el-button type="primary" plain :loading="savingProjectRole === role.id" @click="saveProjectRole(role)">保存</el-button></article></div>
    </el-dialog>
    <el-dialog v-model="storyboardEditorVisible" title="编辑分镜" width="620px" class="storyboard-editor-dialog">
      <el-form v-if="storyboardDraft" label-position="top"><div class="form-row"><el-form-item label="场号"><el-input v-model="storyboardDraft.scene_no" /></el-form-item><el-form-item label="镜号"><el-input v-model="storyboardDraft.shot_no" /></el-form-item><el-form-item label="时长"><el-input-number v-model="storyboardDraft.duration_seconds" :min="4" :max="12" /></el-form-item></div><el-form-item label="视觉提示词"><el-input v-model="storyboardDraft.visual_prompt" type="textarea" :rows="6" /></el-form-item><div class="form-row"><el-form-item label="镜头语言"><el-input v-model="storyboardDraft.camera" /></el-form-item><el-form-item label="运镜"><el-input v-model="storyboardDraft.motion" /></el-form-item><el-form-item label="画幅"><el-select v-model="storyboardDraft.aspect_ratio"><el-option label="竖屏 9:16（移动端）" value="9:16" /><el-option label="横屏 16:9" value="16:9" /><el-option label="方形 1:1" value="1:1" /></el-select></el-form-item></div><el-form-item label="旁白"><el-input v-model="storyboardDraft.narration" type="textarea" :rows="3" /></el-form-item><el-form-item label="对白"><el-input v-model="storyboardDraft.dialogue" type="textarea" :rows="3" /></el-form-item><el-form-item label="连续性参考资产"><div class="storyboard-reference-help">选择角色、场景或当前镜头参考图。生成时会自动作为参考图提交，最多 5 张。</div><div class="storyboard-reference-assets"><button v-for="asset in referenceAssetsForStoryboard.filter((item) => item.asset_type !== 'storyboard_reference' || item.storyboard_shot_index === selectedStoryboardIndex)" :key="asset.id" type="button" class="storyboard-reference-asset" :class="{ 'is-selected': storyboardDraft.reference_asset_ids?.includes(asset.id) }" @click="toggleStoryboardReferenceAsset(asset.id)"><el-image v-if="asset.results?.[0]" :src="asset.results.find((item) => item.status === 'success')?.local_url || asset.results.find((item) => item.status === 'success')?.image_url" fit="cover" /><strong>{{ asset.title }}</strong><span>{{ { character: '角色', scene: '场景', storyboard_reference: '本镜头' }[asset.asset_type] }}</span></button></div><el-empty v-if="!referenceAssetsForStoryboard.length" description="请先生成角色、场景或分镜参考图" :image-size="70" /></el-form-item></el-form>
      <template #footer><el-button @click="storyboardEditorVisible = false">取消</el-button><el-button type="primary" :loading="savingStoryboard" @click="saveStoryboardShot">保存分镜</el-button></template>
    </el-dialog>
    <el-dialog v-model="assetVisible" title="影视界素材库" width="680px" class="asset-dialog">
      <el-alert type="info" :closable="false" title="Agnes 仅接受上游可公开访问的素材 URL。本素材库会在当前浏览器保存 URL，便于复用。" />
      <div class="asset-add-row"><el-input v-model="newAsset.name" placeholder="素材名称" /><el-select v-model="newAsset.type"><el-option label="图片" value="image" /><el-option label="音频" value="audio" /></el-select><el-input v-model="newAsset.url" placeholder="https://公开素材地址" /><el-button type="primary" @click="addAsset">保存 URL</el-button></div>
      <div class="asset-upload-row"><el-upload :show-file-list="false" :before-upload="uploadAsset"><el-button :loading="uploadingAsset">上传本地图片 / 音频</el-button></el-upload><span>支持 JPEG、PNG、WebP、MP3、WAV、OGG、M4A，最大 25MB</span></div>
