      <div v-else class="asset-list"><article v-for="asset in assets" :key="asset.id" class="asset-item"><img v-if="asset.type === 'image'" :src="asset.url" :alt="asset.name" /><div class="asset-info"><strong>{{ asset.name }}</strong><span>{{ asset.type === 'image' ? '图片' : '音频' }} · {{ asset.url }}</span></div><div class="asset-actions"><el-button size="small" @click="useAsset(asset)">使用</el-button><el-button size="small" text type="danger" @click="removeAsset(asset.id)">删除</el-button></div></article></div>
