    <el-dialog v-model="canvasVisible" title="影视界创作画布" width="94%" top="4vh" class="canvas-dialog">
      <div class="canvas-toolbar">
        <span>拖拽节点编排素材与视频任务，滚轮缩放，按住空白区域拖动平移。</span>
        <div><el-button size="small" @click="resetCanvas">重置视图</el-button><el-button size="small" @click="autoLayout">自动布局</el-button></div>
      </div>
      <div ref="canvasViewport" class="canvas-viewport" @wheel.prevent="handleCanvasWheel" @pointerdown="startPan" @pointermove="moveCanvas" @pointerup="stopCanvas" @pointerleave="stopCanvas">
        <div class="canvas-grid" :style="canvasStyle">
          <svg class="canvas-links" :viewBox="`0 0 ${canvasSize.width} ${canvasSize.height}`"><line v-for="link in canvasLinks" :key="link.id" :x1="link.x1" :y1="link.y1" :x2="link.x2" :y2="link.y2" /></svg>
          <article v-for="node in canvasNodes" :key="node.id" class="canvas-node" :class="`canvas-node--${node.kind}`" :style="nodeStyle(node)" @pointerdown.stop="startNodeDrag($event, node)" @dblclick="applyNode(node)">
            <div class="canvas-node__head"><span>{{ node.kind === 'result' ? '视频结果' : '生成任务' }}</span><el-tag size="small" :type="statusType(node.status)">{{ statusLabel(node.status) }}</el-tag></div>
            <strong>{{ node.model }}</strong><p>{{ node.prompt }}</p><small>{{ node.mode }} · {{ node.seconds }} 秒</small>
            <video v-if="node.video_url" :src="node.video_url" muted preload="metadata" />
