    <el-dialog v-model="videoTaskDetailVisible" title="视频任务详情" width="720px" class="video-task-detail-dialog">
      <template v-if="selectedVideoTask">
        <el-descriptions :column="2" border size="small">
          <el-descriptions-item label="任务 ID">#{{ selectedVideoTask.id }}</el-descriptions-item>
          <el-descriptions-item label="状态">{{ statusLabel(selectedVideoTask.status) }}</el-descriptions-item>
          <el-descriptions-item label="模型">{{ selectedVideoTask.model }}</el-descriptions-item>
          <el-descriptions-item label="Provider">{{ selectedVideoTask.provider || '-' }}</el-descriptions-item>
