      <el-alert v-if="models.some((item) => item.is_duplicate)" class="model-duplicate-alert" type="warning" :closable="false" title="存在重复模型 ID：请保留一条启用配置，再手动编辑或删除其余记录。系统不会自动合并或删除。" />
      <el-table :data="models" class="model-table"><el-table-column label="模型" min-width="190"><template #default="{ row }"><span>{{ row.display_name }}</span><el-tag v-if="row.is_duplicate" size="small" type="warning" effect="plain" class="model-duplicate-tag">重复 {{ row.duplicate_count }} 条</el-tag><small class="model-id">{{ row.model }}</small></template></el-table-column><el-table-column prop="provider" label="Provider" width="120" /><el-table-column prop="protocol" label="协议" min-width="150" /><el-table-column prop="available_key_count" label="可用 Key" width="90" /><el-table-column label="操作" width="155"><template #default="{ row }"><el-button size="small" text type="primary" @click="editModel(row)">编辑</el-button><el-button size="small" text type="danger" :disabled="row.model === 'agnes-video-2.5-flash'" @click="removeModel(row)">删除</el-button></template></el-table-column></el-table>
