      <el-form label-position="top"><el-form-item label="端点模板"><el-select placeholder="选择模板后自动填充协议与端点" @change="applyEndpointTemplate"><el-option v-for="item in endpointTemplates" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><div class="form-row"><el-form-item label="模型 ID"><el-input v-model="newModel.model" :readonly="Boolean(editingModelId)" /><small v-if="editingModelId" class="model-id-hint">模型 ID 关联历史任务和 Key 匹配，不能修改；如需新 ID，请新增配置。</small></el-form-item><el-form-item label="展示名称"><el-input v-model="newModel.display_name" /></el-form-item></div><div class="form-row"><el-form-item label="Provider"><el-input v-model="newModel.provider" /></el-form-item><el-form-item label="协议"><el-select v-model="newModel.protocol" @change="applyProtocolDefaults"><el-option label="Agnes Videos" value="agnes" /><el-option label="ArcReel NewAPI Video" value="arcreel_newapi_video" /><el-option label="ArcReel MiniMax H3" value="arcreel_minimax_h3" /><el-option label="ArcReel MiniMax Hailuo" value="arcreel_minimax_hailuo" /><el-option label="ArcReel MiniMax S2V" value="arcreel_minimax_s2v" /><el-option label="ArcReel V2 Video Generations" value="arcreel_v2_video" /><el-option label="MiniMax 自定义协议" value="minimax" /></el-select></el-form-item></div><div class="form-row"><el-form-item label="创建任务路径"><el-input v-model="newModel.create_path" /></el-form-item><el-form-item label="查询任务路径"><el-input v-model="newModel.query_path" /></el-form-item></div><el-form-item><el-checkbox v-model="newModel.enabled">启用此模型配置</el-checkbox></el-form-item><el-form-item label="模型能力 JSON"><el-input v-model="newModel.capabilities_text" type="textarea" :rows="5" placeholder="填写此模型实际支持的 modes、seconds、sizes、aspect_ratios" /></el-form-item></el-form>
      <template #footer><el-button @click="configVisible = false">关闭</el-button><el-button type="primary" :loading="savingModel" @click="saveModel">{{ editingModelId ? '保存修改' : '添加模型' }}</el-button></template>
    </el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
import { adminApi } from '../api'

const stylePresets = ref([])
