const visibleStylePresets = computed(() => stylePresets.value.filter((item) => item.category === styleCategory.value))
const displayedTasks = computed(() => videoHistoryExpanded.value ? tasks.value : tasks.value.slice(0, 1))
const selectStylePreset = (preset) => { selectedStyleId.value = preset.id; styleCategory.value = preset.category; stylePickerExpanded.value = false }
const clearStylePreset = () => { selectedStyleId.value = "" }
const openVideoTaskDetail = (task) => { selectedVideoTask.value = task; videoTaskDetailVisible.value = true }
const appendVisualStyle = (prompt, style) => { const base = String(prompt || '').trim(); const normalizedStyle = String(style || '').trim(); if (!normalizedStyle || base.toLowerCase().includes(normalizedStyle.toLowerCase())) return base; return `${base}\n\nVisual style: ${normalizedStyle}` }
const promptWithStyle = (prompt) => prompt

const models = ref([])
const endpointTemplates = ref([])
const tasks = ref([])
const loading = ref(false)
const generating = ref(false)
const refreshingId = ref(null)
const taskPolling = ref({})
let taskRefreshTimer = null
const configVisible = ref(false)
const savingModel = ref(false)
const canvasVisible = ref(false)
const canvasViewport = ref(null)
const canvasSize = { width: 2400, height: 1500 }
const canvas = ref({ x: 60, y: 60, scale: 0.72 })
const canvasNodes = ref([])
let panState = null
let dragState = null
const assetVisible = ref(false)
const assets = ref([])
const newAsset = ref({ name: '', type: 'image', url: '' })
const uploadingAsset = ref(false)
const agentVisible = ref(false)
const creativeProjects = ref([])
const creativeProject = ref(null)
const creativeDraft = ref({ title: '', source_text: '', default_aspect_ratio: '9:16' })
const creativeDraftFiles = ref([])
