const projectRoles = ref([])
const roleConfigVisible = ref(false)
const savingProjectRole = ref(false)
const creativeAgentSources = ref({ providers: [], keys: [] })
const productionRoles = ref([
  { id: 'text', label: '文本 Agent', description: '小说分析、剧本与分镜', model: '', source_mode: 'auto', provider: '', api_key_id: undefined, endpoint_template_id: '', enabled: true },
  { id: 'image', label: '图片生成', description: '角色、场景与分镜参考图', model: '', source_mode: 'auto', provider: '', api_key_id: undefined, endpoint_template_id: '', enabled: false },
  { id: 'video', label: '视频生成', description: '分镜视频片段', model: '', source_mode: 'auto', provider: '', api_key_id: undefined, endpoint_template_id: '', enabled: true },
  { id: 'tts', label: 'TTS 配音', description: '旁白与角色配音', model: '', source_mode: 'auto', provider: '', api_key_id: undefined, endpoint_template_id: '', enabled: false },
  { id: 'asr', label: 'ASR 字幕', description: '音频识别与字幕时间轴', model: '', source_mode: 'auto', provider: '', api_key_id: undefined, endpoint_template_id: '', enabled: false },
])
const loadingCreativeSources = ref(false)
const creatingCreativeProject = ref(false)
const creativeRunning = ref('')
const agentPanels = ref(['analysis'])
const projectAudioTasks = ref([])
const projectSubtitleTasks = ref([])
const projectVideoTasks = ref([])
const projectImageAssets = ref([])
const projectAttachments = ref([])
const projectWorkflow = ref(null)
const directorStatus = ref(null)
const directorRunning = ref('')
const creatingWorkflowPlan = ref(false)
const reviewingWorkflow = ref(false)
const uploadingProjectAttachment = ref(false)
const projectImageDraft = ref({ asset_type: 'character', title: '', prompt: '', storyboard_shot_index: undefined })
const creatingProjectImage = ref(false)
const projectTimeline = ref([])
const projectExports = ref([])
const ffmpegPreflight = ref(null)
const creatingProjectExport = ref(false)
const projectExportAudioStrategy = ref('preserve')
const selectedStoryboardIndexes = ref([])
const generatingStoryboard = ref(false)
const storyboardConcurrency = ref(2)
const retryingStoryboard = ref(null)
const projectVoiceProfiles = ref([])
const voiceProfileDraft = ref({ profile_type: 'narrator', name: '旁白', character_asset_id: undefined, voice: 'alloy' })
const savingVoiceProfile = ref(false)
const audioDraft = ref({ text: '', voice: 'alloy', speaker_type: 'narrator', character_asset_id: undefined, voice_profile_id: undefined, speaker_name: '' })
const creatingAudio = ref(false)
const audioQueueBusy = ref(null)
const creatingSubtitle = ref(null)
const savingSubtitle = ref(null)
const savingTimelineItem = ref(null)
const selectedStoryboardIndex = ref(-1)
const storyboardEditorVisible = ref(false)
const storyboardDraft = ref(null)
const savingStoryboard = ref(false)
const referenceAudios = ref('')
const form = ref({ model: '', source: '', mode: 'text', seconds: '5', aspect_ratio: '16:9', seed: undefined, prompt: '', first_frame: '', last_frame: '' })
const defaultModelDraft = () => ({ model: '', display_name: '', provider: '', protocol: 'arcreel_newapi_video', create_path: '/v1/video/generations', query_path: '/v1/video/generations', enabled: true, capabilities_text: '{\n  "modes": ["text", "keyframe"],\n  "seconds": ["4", "5", "6", "7", "8", "9", "10", "11", "12"],\n  "sizes": ["720P"],\n  "aspect_ratios": ["16:9", "9:16", "1:1"]\n}' })
const newModel = ref(defaultModelDraft())
const editingModelId = ref(null)
const currentModel = computed(() => models.value.find((item) => item.model === form.value.model))
const secondsOptions = computed(() => currentModel.value?.capabilities?.seconds || ['4', '5', '6', '7', '8', '9', '10', '11', '12'])
const ratioOptions = computed(() => currentModel.value?.capabilities?.aspect_ratios || ['16:9', '9:16', '1:1'])
const sources = computed(() => { const seen = new Set(); const values = []; models.value.forEach((model) => { if (model.provider && !seen.has(`provider:${model.provider}`)) { seen.add(`provider:${model.provider}`); values.push({ label: `Provider：${model.provider}（自动轮询）`, value: `provider:${model.provider}` }) }; (model.available_keys || []).forEach((key) => { if (!seen.has(`key:${key.id}`)) { seen.add(`key:${key.id}`); values.push({ label: `${key.provider} | #${key.id} ${key.name}`, value: `key:${key.id}` }) } }) }); return values })
const creativeStageIndex = computed(() => creativeProject.value?.storyboard?.length ? 3 : creativeProject.value?.script?.episodes?.length ? 2 : creativeProject.value?.analysis?.summary ? 1 : 0)
const workflowStatusLabel = computed(() => ({ draft: '待生成计划', awaiting_plan_review: '等待计划审核', awaiting_analysis_review: '等待分析审核', awaiting_script_review: '等待剧本审核', awaiting_storyboard_review: '等待分镜审核', running: '后台执行中', paused: '已暂停', completed: '已完成', failed: '执行失败', cancelled: '已取消' }[projectWorkflow.value?.status] || '尚未建立'))
const directorReviewLabel = computed(() => ({ awaiting_storyboard_review: '等待审核', approved: '已审核', running: '生产中', ready: '可生产', completed: '已完成' }[directorStatus.value?.review_status] || '未建立'))
const directorCompletedShotCount = computed(() => (directorStatus.value?.shot_statuses || []).filter((item) => item.status === 'completed').length)
const directorBlockers = computed(() => (directorStatus.value?.shot_statuses || []).filter((item) => item.status === 'failed' || item.status === 'planned'))
const projectVisualStyle = computed(() => String(projectWorkflow.value?.plan?.visual_style || '').trim())
const workflowTaskLabel = (status) => ({ blocked: '等待前置阶段', pending: '待执行', running: '执行中', completed: '已完成', failed: '失败', cancelled: '已取消' }[status] || status)
const workflowTaskType = (status) => ({ completed: 'success', failed: 'danger', running: 'warning', pending: 'primary' }[status] || 'info')
const storyboardTaskByIndex = computed(() => Object.fromEntries(projectVideoTasks.value.filter((task) => task.storyboard_shot_index !== null && task.storyboard_shot_index !== undefined).map((task) => [task.storyboard_shot_index, task])))
const selectedStoryboardVideoIds = computed(() => new Set(projectTimeline.value.filter((item) => item.track === 'video' && item.storyboard_shot_index !== null && item.storyboard_shot_index !== undefined).map((item) => item.source_id)))
const timelineVideoItems = computed(() => projectTimeline.value.filter((item) => item.track === 'video').sort((a, b) => a.position - b.position))
const previewVideoUrl = computed(() => projectExports.value.find((item) => item.status === 'completed')?.download_url || projectVideoTasks.value.find((task) => timelineVideoItems.value.some((item) => item.source_id === task.id))?.video_url || '')
const previewAspectRatio = computed(() => creativeProject.value?.default_aspect_ratio || '9:16')
const referenceAssetsForStoryboard = computed(() => projectImageAssets.value.filter((asset) => asset.status === 'completed' && (asset.asset_type === 'character' || asset.asset_type === 'scene' || asset.asset_type === 'storyboard_reference')))
const characterAssets = computed(() => projectImageAssets.value.filter((asset) => asset.status === 'completed' && asset.asset_type === 'character'))
const selectedVoiceProfiles = computed(() => projectVoiceProfiles.value.filter((item) => item.profile_type === audioDraft.value.speaker_type && (item.profile_type !== 'character' || item.character_asset_id === audioDraft.value.character_asset_id)))
const selectCreativeProject = async (project) => { creativeProject.value = project; selectedStoryboardIndexes.value = []; projectVoiceProfiles.value = []; directorStatus.value = null; agentPanels.value = project.storyboard?.length ? ['storyboard'] : project.script?.episodes?.length ? ['script'] : ['analysis']; try { const [configs, audioTasks, subtitleTasks, videoTasks, imageAssets, attachments, workflow, timeline, exports, preflight, voiceProfiles, director] = await Promise.all([adminApi.listCreativeProjectRoles(project.id), adminApi.listProjectAudio(project.id), adminApi.listProjectSubtitles(project.id), adminApi.listProjectVideoTasks(project.id), adminApi.listProjectImages(project.id), adminApi.listProjectAttachments(project.id), adminApi.getProjectWorkflow(project.id), adminApi.listProjectTimeline(project.id), adminApi.listProjectExports(project.id), adminApi.getVideoFfmpegPreflight(), adminApi.listProjectVoiceProfiles(project.id), adminApi.getDirectorStatus(project.id)]); productionRoles.value = productionRoles.value.map((role) => ({ ...role, ...(configs.find((item) => item.role === role.id) || {}) })); projectAudioTasks.value = audioTasks || []; projectSubtitleTasks.value = subtitleTasks || []; projectVoiceProfiles.value = voiceProfiles || []; projectVideoTasks.value = videoTasks || []; projectImageAssets.value = imageAssets || []; projectAttachments.value = attachments || []; projectWorkflow.value = workflow; projectTimeline.value = timeline || []; projectExports.value = exports || []; ffmpegPreflight.value = preflight; directorStatus.value = director || null } catch (error) { ElMessage.error(error.message) } }
const createWorkflowPlan = async () => { if (!creativeProject.value || !creativeAgent.value.model.trim()) return ElMessage.warning('请先填写可用的文本模型作为总控 Agent'); creatingWorkflowPlan.value = true; try { projectWorkflow.value = await adminApi.createProjectWorkflowPlan(creativeProject.value.id, { model: creativeAgent.value.model.trim(), source: creativeAgent.value.source.trim() || undefined }); ElMessage.success('制作计划已生成，请审核后继续') } catch (error) { ElMessage.error(error.message) } finally { creatingWorkflowPlan.value = false } }
const refreshDirectorStatus = async () => { if (!creativeProject.value) return; directorStatus.value = await adminApi.getDirectorStatus(creativeProject.value.id) }
const runDirectorStoryboard = async () => { if (!creativeProject.value || !creativeAgent.value.model.trim()) return ElMessage.warning('请先填写可用的文本模型'); directorRunning.value = 'storyboard'; try { const result = await adminApi.createDirectorStoryboard(creativeProject.value.id, { model: creativeAgent.value.model.trim(), source: creativeAgent.value.source.trim() || undefined, aspect_ratio: creativeProject.value.default_aspect_ratio }); directorStatus.value = await adminApi.getDirectorStatus(creativeProject.value.id); const updated = await adminApi.listCreativeProjects(); creativeProjects.value = updated; creativeProject.value = updated.find((item) => item.id === creativeProject.value.id) || creativeProject.value; ElMessage.success(`已生成 ${result.shots?.length || 0} 个导演分镜，请审核后批量生产`) } catch (error) { ElMessage.error(error.message) } finally { directorRunning.value = '' } }
const produceDirectorShots = async () => { if (!creativeProject.value || !directorStatus.value?.shots?.length) return; directorRunning.value = 'produce'; try { const result = await adminApi.produceDirectorShots(creativeProject.value.id, { regenerate_failed: true, video_concurrency: storyboardConcurrency.value, audio_concurrency: storyboardConcurrency.value, subtitle_concurrency: 1 }); projectVideoTasks.value = await adminApi.listProjectVideoTasks(creativeProject.value.id); await refreshDirectorStatus(); ElMessage.success(`已提交 ${result.created_task_ids?.length || 0} 个镜头，复用 ${result.reused_task_ids?.length || 0} 个已有结果`) } catch (error) { ElMessage.error(error.message) } finally { directorRunning.value = '' } }
const produceDirectorShot = async (shotIndex) => { if (!creativeProject.value) return; directorRunning.value = `produce-${shotIndex}`; try { const result = await adminApi.produceDirectorShots(creativeProject.value.id, { shot_indexes: [shotIndex], regenerate_failed: true }); await selectCreativeProject(creativeProject.value); ElMessage.success(`镜 ${shotIndex + 1} 已提交 ${result.created_task_ids?.length || 0} 个视频任务`) } catch (error) { ElMessage.error(error.message) } finally { directorRunning.value = '' } }
const autoScheduleDirector = async () => { if (!creativeProject.value) return; directorRunning.value = 'schedule'; try { const result = await adminApi.autoScheduleDirectorProject(creativeProject.value.id, { audio_strategy: projectExportAudioStrategy.value, include_audio: true, include_subtitles: true }); if (!result.scheduled) { ElMessage.warning(`暂不能排片：${(result.blockers || []).map((item) => `镜 ${Number(item.shot_index) + 1} ${item.reason}`).join('；')}`); return } projectTimeline.value = await adminApi.listProjectTimeline(creativeProject.value.id); await refreshDirectorStatus(); ElMessage.success(`已自动排入 ${result.video_count} 个镜头，预计 ${(result.timeline_duration_ms / 1000).toFixed(1)} 秒`) } catch (error) { ElMessage.error(error.message) } finally { directorRunning.value = '' } }
const reviewWorkflow = async (action) => { if (!creativeProject.value) return; reviewingWorkflow.value = true; try { projectWorkflow.value = await adminApi.reviewProjectWorkflow(creativeProject.value.id, { action }); ElMessage.success(action === 'approve' ? '已批准，工作流将后台推进' : action === 'pause' ? '工作流已暂停' : '工作流已恢复') } catch (error) { ElMessage.error(error.message) } finally { reviewingWorkflow.value = false } }
const openProjectRoles = () => { roleConfigVisible.value = true }
const uploadProjectAttachment = async (file) => { if (!creativeProject.value) return false; uploadingProjectAttachment.value = true; try { const attachment = await adminApi.uploadProjectAttachment(creativeProject.value.id, file); projectAttachments.value.unshift(attachment); ElMessage.success('附件已提取并加入项目资料') } catch (error) { ElMessage.error(error.message) } finally { uploadingProjectAttachment.value = false }; return false }
const removeProjectAttachment = async (attachment) => { if (!creativeProject.value) return; try { await adminApi.deleteProjectAttachment(creativeProject.value.id, attachment.id); projectAttachments.value = projectAttachments.value.filter((item) => item.id !== attachment.id); ElMessage.success('附件已移除') } catch (error) { ElMessage.error(error.message) } }
const createProjectImage = async () => { if (!creativeProject.value || !projectImageDraft.value.title.trim() || !projectImageDraft.value.prompt.trim()) return ElMessage.warning('请填写资产名称和图片提示词，并在生产职责中配置图片模型'); if (projectImageDraft.value.asset_type === 'storyboard_reference' && !Number.isInteger(projectImageDraft.value.storyboard_shot_index)) return ElMessage.warning('请选择关联分镜'); creatingProjectImage.value = true; try { const asset = await adminApi.createProjectImage(creativeProject.value.id, { asset_type: projectImageDraft.value.asset_type, title: projectImageDraft.value.title.trim(), prompt: projectImageDraft.value.prompt.trim(), storyboard_shot_index: projectImageDraft.value.asset_type === 'storyboard_reference' ? projectImageDraft.value.storyboard_shot_index : undefined }); projectImageAssets.value.unshift(asset); projectImageDraft.value = { asset_type: 'character', title: '', prompt: '', storyboard_shot_index: undefined }; ElMessage.success('项目图片任务已创建') } catch (error) { ElMessage.error(error.message) } finally { creatingProjectImage.value = false } }
const createAudio = async () => { if (!creativeProject.value || !audioDraft.value.text.trim()) return ElMessage.warning('请填写配音内容并在生产职责中配置 TTS 模型'); if (audioDraft.value.speaker_type === 'character' && !audioDraft.value.character_asset_id && !audioDraft.value.speaker_name.trim()) return ElMessage.warning('请选择角色或填写角色名称'); creatingAudio.value = true; try { const task = await adminApi.createProjectAudio(creativeProject.value.id, { text: audioDraft.value.text.trim(), voice: audioDraft.value.voice, speaker_type: audioDraft.value.speaker_type, character_asset_id: audioDraft.value.character_asset_id, voice_profile_id: audioDraft.value.voice_profile_id, speaker_name: audioDraft.value.speaker_name.trim() || undefined }); projectAudioTasks.value.unshift(task); audioDraft.value.text = ''; ElMessage.success('配音已加入队列') } catch (error) { ElMessage.error(error.message) } finally { creatingAudio.value = false } }
const moveAudioQueueItem = async (item, direction) => { if (!creativeProject.value || item.status !== 'pending') return; const pending = projectAudioTasks.value.filter((entry) => entry.status === 'pending').sort((a, b) => (a.queue_position ?? 999999) - (b.queue_position ?? 999999)); const index = pending.findIndex((entry) => entry.id === item.id); const target = pending[index + direction]; if (!target) return; audioQueueBusy.value = item.id; try { await adminApi.updateProjectAudioQueuePosition(creativeProject.value.id, item.id, index + direction); projectAudioTasks.value = await adminApi.listProjectAudio(creativeProject.value.id) } catch (error) { ElMessage.error(error.message) } finally { audioQueueBusy.value = null } }
