const canvasStyle = computed(() => ({ width: `${canvasSize.width}px`, height: `${canvasSize.height}px`, transform: `translate(${canvas.value.x}px, ${canvas.value.y}px) scale(${canvas.value.scale})` }))
const canvasLinks = computed(() => canvasNodes.value.slice(1).map((node, index) => ({ id: `${canvasNodes.value[index].id}-${node.id}`, x1: canvasNodes.value[index].x + 280, y1: canvasNodes.value[index].y + 80, x2: node.x, y2: node.y + 80 })))
