const persistCanvas = () => localStorage.setItem(CANVAS_STORAGE_KEY, JSON.stringify({ canvas: canvas.value, nodes: canvasNodes.value.map(({ x, y, id }) => ({ id, x, y })) }))
const rebuildCanvasNodes = () => { const positions = (() => { try { return new Map((JSON.parse(localStorage.getItem(CANVAS_STORAGE_KEY) || '{}').nodes || []).map((item) => [item.id, item])) } catch { return new Map() } })(); canvasNodes.value = tasks.value.flatMap((task, index) => { const x = positions.get(`task-${task.id}`)?.x ?? 100 + (index % 3) * 420; const y = positions.get(`task-${task.id}`)?.y ?? 100 + Math.floor(index / 3) * 280; const base = { ...task, id: `task-${task.id}`, x, y, kind: 'task' }; const resultPosition = positions.get(`result-${task.id}`); return task.video_url ? [base, { ...task, id: `result-${task.id}`, x: resultPosition?.x ?? x + 310, y: resultPosition?.y ?? y + 110, kind: 'result' }] : [base] }) }
const restoreCanvas = () => { try { const stored = JSON.parse(localStorage.getItem(CANVAS_STORAGE_KEY) || '{}'); if (stored.canvas) canvas.value = stored.canvas } catch {} }
const resetCanvas = () => { canvas.value = { x: 60, y: 60, scale: 0.72 }; persistCanvas() }
const autoLayout = () => { localStorage.removeItem(CANVAS_STORAGE_KEY); rebuildCanvasNodes(); resetCanvas() }
const handleCanvasWheel = (event) => { const delta = event.deltaY > 0 ? -0.08 : 0.08; canvas.value.scale = Math.min(1.5, Math.max(0.35, canvas.value.scale + delta)); persistCanvas() }
const startPan = (event) => { if (event.button !== 0) return; panState = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, canvasX: canvas.value.x, canvasY: canvas.value.y }; event.currentTarget.setPointerCapture?.(event.pointerId) }
const moveCanvas = (event) => { if (dragState) { const node = canvasNodes.value.find((item) => item.id === dragState.id); if (node) { node.x = Math.max(0, dragState.nodeX + (event.clientX - dragState.x) / canvas.value.scale); node.y = Math.max(0, dragState.nodeY + (event.clientY - dragState.y) / canvas.value.scale) } return }; if (!panState || panState.pointerId !== event.pointerId) return; canvas.value.x = panState.canvasX + event.clientX - panState.x; canvas.value.y = panState.canvasY + event.clientY - panState.y }
const stopCanvas = () => { if (panState || dragState) persistCanvas(); panState = null; dragState = null }
