const pollingState = (taskId) => taskPolling.value[taskId] || { failures: 0, nextAt: 0, limited: false }
const pollingWaitSeconds = (taskId) => Math.max(0, Math.ceil((pollingState(taskId).nextAt - Date.now()) / 1000))
const schedulePolling = (taskId, failures = 0, retryAfterSeconds = 0) => { const delay = retryAfterSeconds > 0 ? retryAfterSeconds * 1000 : Math.min(60000, 15000 * (2 ** Math.min(failures, 2))); taskPolling.value = { ...taskPolling.value, [taskId]: { failures, nextAt: Date.now() + delay, limited: retryAfterSeconds > 0 } } }
const refresh = async (task, silent = false) => { const state = pollingState(task.id); if (state.nextAt > Date.now()) { if (!silent) ElMessage.warning(`该任务将在 ${pollingWaitSeconds(task.id)} 秒后自动查询`); return }; refreshingId.value = task.id; try { const updated = await adminApi.refreshVideoTask(task.id); const index = tasks.value.findIndex((item) => item.id === task.id); if (index >= 0) tasks.value.splice(index, 1, updated); if (['pending', 'creating', 'running'].includes(updated.status)) schedulePolling(task.id); else { const { [task.id]: _removed, ...rest } = taskPolling.value; taskPolling.value = rest } } catch (error) { const retryAfter = Number(error.response?.headers?.['retry-after']) || 0; const isLimited = error.response?.status === 429; schedulePolling(task.id, pollingState(task.id).failures + 1, isLimited ? retryAfter || 60 : 0); if (!silent) ElMessage.error(isLimited ? `上游限流，将在 ${pollingWaitSeconds(task.id)} 秒后重试查询` : error.message) } finally { refreshingId.value = null } }
const refreshProjectVideoTask = async (task) => { const state = pollingState(task.id); if (state.nextAt > Date.now()) return ElMessage.warning(`该任务将在 ${pollingWaitSeconds(task.id)} 秒后自动查询`); refreshingId.value = task.id; try { const updated = await adminApi.refreshVideoTask(task.id); const index = projectVideoTasks.value.findIndex((item) => item.id === task.id); if (index >= 0) projectVideoTasks.value.splice(index, 1, updated); if (['pending', 'creating', 'running'].includes(updated.status)) schedulePolling(task.id); const timeline = await adminApi.listProjectTimeline(creativeProject.value.id); projectTimeline.value = timeline || [] } catch (error) { const retryAfter = Number(error.response?.headers?.['retry-after']) || 0; const isLimited = error.response?.status === 429; schedulePolling(task.id, pollingState(task.id).failures + 1, isLimited ? retryAfter || 60 : 0); ElMessage.error(isLimited ? `上游限流，将在 ${pollingWaitSeconds(task.id)} 秒后重试查询` : error.message) } finally { refreshingId.value = null } }
const selectStoryboardVideoCandidate = async (task) => { if (!creativeProject.value || task.storyboard_shot_index === null || task.storyboard_shot_index === undefined) return; try { await adminApi.selectStoryboardVideoCandidate(creativeProject.value.id, task.storyboard_shot_index, task.id); projectTimeline.value = await adminApi.listProjectTimeline(creativeProject.value.id); ElMessage.success(`已将镜 ${task.storyboard_shot_index + 1} 设为定稿`) } catch (error) { ElMessage.error(error.message) } }
const retryStoryboardVideo = async (task) => { if (!creativeProject.value) return; retryingStoryboard.value = task.storyboard_shot_index; try { const result = await adminApi.generateStoryboardVideos(creativeProject.value.id, { selected_shot_indexes: [task.storyboard_shot_index], concurrency: 1 }); const replacement = result.items?.[0]; if (replacement) { const index = projectVideoTasks.value.findIndex((item) => item.id === task.id); if (index >= 0) projectVideoTasks.value.splice(index, 1, replacement); } ElMessage.success('已重新提交分镜视频') } catch (error) { ElMessage.error(error.message) } finally { retryingStoryboard.value = null } }
const refreshActiveTasks = async () => { const activeTasks = tasks.value.filter((task) => ['pending', 'creating', 'running'].includes(task.status)); await Promise.all(activeTasks.map((task) => refresh(task, true))); if (creativeProject.value) { const activeProjectTasks = projectVideoTasks.value.filter((task) => ['pending', 'creating', 'running'].includes(task.status)); await Promise.all(activeProjectTasks.map((task) => refreshProjectVideoTask(task))); if (projectImageAssets.value.some((asset) => asset.status === 'running')) projectImageAssets.value = await adminApi.listProjectImages(creativeProject.value.id); if (projectAudioTasks.value.some((task) => ['pending', 'running'].includes(task.status))) projectAudioTasks.value = await adminApi.listProjectAudio(creativeProject.value.id); if (projectSubtitleTasks.value.some((task) => ['pending', 'running'].includes(task.status))) projectSubtitleTasks.value = await adminApi.listProjectSubtitles(creativeProject.value.id); if (projectWorkflow.value && ['running', 'paused'].includes(projectWorkflow.value.status)) projectWorkflow.value = await adminApi.getProjectWorkflow(creativeProject.value.id); if (directorStatus.value) directorStatus.value = await adminApi.getDirectorStatus(creativeProject.value.id); if (projectExports.value.some((item) => ['pending', 'running'].includes(item.status))) projectExports.value = await adminApi.listProjectExports(creativeProject.value.id) } }
const removeTask = async (task) => { try { await ElMessageBox.confirm(`确认删除视频任务 #${task.id} 吗？`, '删除视频任务', { type: 'warning' }); await adminApi.deleteVideoTask(task.id); tasks.value = tasks.value.filter((item) => item.id !== task.id); ElMessage.success('视频任务已删除') } catch (error) { if (error !== 'cancel') ElMessage.error(error.message || '删除失败') } }
const removeModel = async (model) => { try { await ElMessageBox.confirm(`确认删除视频模型 ${model.display_name} 吗？`, '删除视频模型', { type: 'warning' }); await adminApi.deleteVideoModel(model.id); await loadAll(); ElMessage.success('视频模型已删除') } catch (error) { if (error !== 'cancel') ElMessage.error(error.message || '删除失败') } }
const editModel = (model) => { editingModelId.value = model.id; newModel.value = { model: model.model, display_name: model.display_name, provider: model.provider || '', protocol: model.protocol, create_path: model.create_path, query_path: model.query_path, enabled: model.enabled, capabilities_text: JSON.stringify(model.capabilities || {}, null, 2) } }
const resetModelForm = () => { editingModelId.value = null; newModel.value = defaultModelDraft() }
const saveModel = async () => { if (!newModel.value.model.trim() || !newModel.value.display_name.trim()) return ElMessage.warning('请填写模型 ID 和展示名称'); let capabilities; try { capabilities = JSON.parse(newModel.value.capabilities_text) } catch { return ElMessage.warning('模型能力 JSON 格式不正确') } savingModel.value = true; try { const { capabilities_text, ...modelData } = newModel.value; const payload = { ...modelData, model: modelData.model.trim(), display_name: modelData.display_name.trim(), provider: modelData.provider.trim() || null, capabilities }; if (editingModelId.value) { await adminApi.updateVideoModel(editingModelId.value, payload); ElMessage.success('视频模型配置已保存') } else { await adminApi.createVideoModel(payload); ElMessage.success('视频模型已添加') } resetModelForm(); await loadAll() } catch (error) { ElMessage.error(error.message) } finally { savingModel.value = false } }
const applyEndpointTemplate = (templateId) => { const template = endpointTemplates.value.find((item) => item.id === templateId); if (!template) return; newModel.value.protocol = template.protocol; newModel.value.create_path = template.create_path; newModel.value.query_path = template.query_path; newModel.value.capabilities_text = JSON.stringify(template.capabilities, null, 2); if (!newModel.value.display_name) newModel.value.display_name = template.name }
const applyProtocolDefaults = (protocol) => { const defaults = { agnes: ['/v1/videos', '/agnesapi'], arcreel_newapi_video: ['/v1/video/generations', '/v1/video/generations'], arcreel_minimax_h3: ['/v2/video_generation', '/v2/query/video_generation'], arcreel_minimax_hailuo: ['/v1/video_generation', '/v1/query/video_generation'], arcreel_minimax_s2v: ['/v1/video_generation', '/v1/query/video_generation'], arcreel_v2_video: ['/v2/video/generations', '/v2/video/generations'] }; const values = defaults[protocol] || ['', '']; newModel.value.create_path = values[0]; newModel.value.query_path = values[1] }
const modeLabel = (value) => ({ text: '文生视频', keyframe: '首尾帧', reference: '参考生成' }[value] || value)
const statusLabel = (value) => ({ pending: '排队中', creating: '创建中', running: '生成中', completed: '已完成', failed: '失败' }[value] || value)
const statusType = (value) => ({ completed: 'success', failed: 'danger', running: 'warning' }[value] || 'info')
const formatTime = (value) => value ? new Date(value).toLocaleString() : '-'
onMounted(async () => { loadAssets(); restoreCanvas(); await Promise.all([loadAll(), loadCreativeProjects()]); taskRefreshTimer = window.setInterval(refreshActiveTasks, 5000) })
onUnmounted(() => { if (taskRefreshTimer) window.clearInterval(taskRefreshTimer) })
